def test_dump_download_and_read_smoke(live_client, tmp_path):
    latest = live_client.dumps.latest()
    path = live_client.dumps.download(latest, tmp_path / "ror-data.zip")
    assert path.stat().st_size > 1_000_000
    records = list(iter_dump_records(path))
    assert len(records) > 100_000
    fundref = index_external_ids(records, "fundref")
    assert "100000001" in fundref
